Instance* Instance::findFirstChildByName(const std::string& findName) const
{
	// rebuild overlay: first direct child with this name
	if (children) {
		for (size_t i = 0; i < children->size(); ++i) {
			if ((*children)[i]->getName() == findName) {
				return (*children)[i].get();
			}
		}
	}
	return NULL;
}

void Instance::setName(const std::string& value)
{
	// rebuild overlay: OpenRBX declares no Name property descriptor, so only the field changes
	name = value;
}

void Instance::predelete()
{
	// rebuild overlay: release the children so none keeps a dangling parent
	if (children) {
		std::vector<shared_ptr<Instance> > copy(*children);
		for (size_t i = 0; i < copy.size(); ++i) {
			copy[i]->setParent(NULL);
		}
	}
}

